import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    s = data[0]
    n = int(data[1])
    word_dict = set(data[2:2+n])

    dp = [False] * (len(s) + 1)
    dp[0] = True
    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_dict:
                dp[i] = True
                break
    print("true" if dp[len(s)] else "false")

if __name__ == '__main__':
    solve()

