#include <stdio.h>
#include <string.h>

char dict[1005][50];
int dictCount;
int dp[305];

int in_dict(const char *sub, int len) {
    for (int i = 0; i < dictCount; i++) {
        if ((int)strlen(dict[i]) == len && strncmp(dict[i], sub, len) == 0) {
            return 1;
        }
    }
    return 0;
}

int main() {
    char s[305];
    if (scanf("%s", s) != 1) return 0;
    if (scanf("%d", &dictCount) != 1) return 0;
    for (int i = 0; i < dictCount; i++) scanf("%s", dict[i]);
    int sLen = strlen(s);
    dp[0] = 1;
    for (int i = 1; i <= sLen; i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] && in_dict(s + j, i - j)) {
                dp[i] = 1;
                break;
            }
        }
    }
    printf("%s\n", dp[sLen] ? "true" : "false");
    return 0;
}
